cd /workspace && echo '--- adapter /docs via backend network ---' && docker exec yii2_vue_dash_container curl -s -o /dev/null -w 'code=%{http_code}
' http://iothubsh-adapter:8000/docs && docker exec yii2_vue_dash_container curl -s http://iothubsh-adapter:8000/openapi.json | head -c 300 && echo && echo '--- traefik HTTP: adapter webhook routes ---' && curl -s -o /dev/null -w 'webhook/config code=%{http_code} redirect=%{redirect_url}
' http://127.0.0.1/webhook/config -H 'Host: localhost' && curl -s -o /dev/null -w 'webhook/measurement code=%{http_code} redirect=%{redirect_url}
' http://127.0.0.1/webhook/measurement -H 'Host: localhost'
